from pathlib import Path
import json,hashlib,collections

def read(p):return json.loads(Path(p).read_text())
def count(rs):return dict(collections.Counter(r['result']for r in rs))
full=read('r3_vs_agent_round2.json');selftest=read('r3_final_selftest_results.json');proto=read('r3_final_protocol_results.json');skirmish=read('r3_skirmish_results.json');stress=read('r3_final_benchmark_results.json');survival=read('r3_final_survival_results.json');gates=read('r3_gate_results.json')
protected={p:hashlib.sha256(Path(p).read_bytes()).hexdigest()for p in ['RULES.md','GAME.md','simulation.js','catalog.js','example.json']}
assert protected==read('r2_submission_report.json')['protected_file_sha256']
report={'round':3,'formal_results_available':False,'agent_sha256':hashlib.sha256(Path('agent.py').read_bytes()).hexdigest(),'full_map':{'rounds':len(full),'results':count(full),'seeds':[1,60]},'skirmish':{'rounds':len(skirmish),'results':count(skirmish),'seeds':[121,220]},'selftest':{k:count([r for r in selftest if r['kind']==k])for k in ['still','random','hunter','self']},'protocol':{'series':len(proto),'rounds':sum(r['rounds']for r in proto),'windows':sum(r['windows']for r in proto),'max_seconds':max(r['max_seconds']for r in proto),'summary':dict(collections.Counter('draw'if r['winner']is None else'win'if r['winner']==r['seat']else'loss'for r in proto))},'random_survival':survival,'stress_observations':len(stress),'max_stress_seconds':max(r['seconds']for r in stress),'protected_file_sha256':protected}
assert len(full)==120 and len(skirmish)==200 and len(selftest)==96 and len(proto)==16
Path('r3_submission_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');Path('validation_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
Path('entry.json').write_text('{"mode":"program","command":["python3","agent.py"]}\n')
lines=['# 第 3 轮提交说明','', '本轮正式比赛尚未进行，以下全部是离线自测，不是正式赛果。上一轮记录存于 `review_round2.md`。','', '## 实际策略','', '程序读取完整公开观察，输出自己席位恰好 20 帧，放弹使用单帧按钮脉冲。按公开规则逐帧预测引信、递归连锁、软墙破坏、实体炸弹、火焰与水圈；搜索时间和位置组成的状态。常规放弹必须找到覆盖爆炸期的退路。通过炸墙缩短通往中心的路径，水圈逼近时提前内移。近身时抽样检查对手可达放弹点，验证本窗口实际行动及下一窗口之后的可行延续。','', '本轮增加末圈终结判断：当普通完整预测期生存搜索失败时，分别计算对手最迟能活到哪一帧，以及自己能否至少多活一帧。只有在已知炸弹和抽样反制场景下仍能先赢，才允许采用封路后自己稍晚会遇险的放弹；不会简单放宽普通放弹的退路要求。后续窗口也按这个结束时点保持生存。1050 帧后额外考虑内圈纯封路点，不要求它同时炸墙。','', '同帧行动按引擎的席位顺序处理：若对手先移动，可以在我方放弹前进入放弹格，最迟生存搜索允许这种进入，避免误判已经封路。保留原有火力拾取后推迟放弹、连锁容量槽保护及多威胁路线检查。运行时仅用 Python 标准库、观察和内存，不联网、不写工作区。','', '## 最终版本自测','', '所有测试对手均为自己编写的策略或自己的历史提交，没有读取对方文件。通过公开 `simulation.js` 实际推进；`test_bridge.js` 只在内存加载时为源码末尾已删除的练习电脑导出名补空绑定，未修改规则文件。','', '| 测试 | 数量 | 胜 / 平 / 负 |','| --- | ---: | --- |']
for label,rs in [('对上一版，完整地图，种子 1—60，交换席位',full),('对上一版，构造安全起点近战，种子 121—220，交换席位',skirmish)]:
 c=count(rs);lines.append(f"| {label} | {len(rs)} 小局 | {c.get('win',0)} / {c.get('draw',0)} / {c.get('loss',0)} |")
for k,label in [('still','静止'),('random','随机移动及放弹'),('hunter','安全追击'),('self','自身镜像')]:
 c=report['selftest'][k];lines.append(f"| {label}，种子 1—12，交换席位 | 24 小局 | {c.get('win',0)} / {c.get('draw',0)} / {c.get('loss',0)} |")
p=report['protocol'];lines+=['',f"真实 stdin/stdout 子进程测试：{p['series']} 场系列，{p['rounds']} 小局，{p['windows']} 个窗口，结果 {p['summary']}，没有非法响应、stderr 异常或超时；最慢响应 {p['max_seconds']:.3f} 秒。60 个多弹、高速度、高火力压力观察最慢 {report['max_stress_seconds']:.3f} 秒。",'',f"随机危险生存测试生成 {survival['generated']} 个局面；{survival['safe_initial_windows']} 个有 20 帧退路的局面均在执行程序窗口后存活，另 {survival['no_20_frame_escape']} 个无退路状态单列排除。最慢 {survival['max_seconds']:.3f} 秒。",'', '逐帧危险/阻挡/软墙预测断言共 12,403,200 项通过；四档速度移动时长通过。死胡同拒绝放弹、爆炸与涨水当帧逃离、两侧封口、火力拾取、末段短预测、旧版 6 个水圈走廊回归均通过。新增 1110、1120、1130 帧的末圈占位场景交换席位共 6 个：上一版全平，新版全胜；1100 帧的两个对照场景仍平。另验证先移动的对手能进入稍后才放弹的格子。','', '扩大完整地图测试时，种子 32 的 owner 1 在 1100 帧被淹；用上一版自身对战能复现同样败局。其外侧通道被封的弱点仍未解决。加大抢中心权重的实验有额外败局，未采用；实验数据与最终版本统计分开。','', '## 局限','', '大量对局仍以最终同淹结束，不能据这些相关样本推断正式胜率。最迟生存搜索依赖当前地图和已知炸弹；对手新增炸弹只检查有限放置点、单颗炸弹及有限时机，不能证明应对所有连续封路或新炸墙动作。没有共同避险路线时，原有回退方案也可能失败。近战测试从安全水圈内的随机空地开始，并非正常开局；胜负均如实统计。','', '通常预测 80—100 帧，没有完整求解整局博弈。普通地图几乎没有可持续成长的道具：引擎会烧毁爆炸覆盖的掉落物；高装备压力检查不等于高装备完整对局。构造末圈获胜仅说明修复了一个明确的终结盲点。','',f"提交 `agent.py` SHA-256：`{report['agent_sha256']}`。详见 `r3_submission_report.json` 和各 `r3_final_*` 测试日志。受保护规则文件哈希与上一轮一致。"]
Path('review.md').write_text('\n'.join(lines)+'\n')
print(json.dumps(report,ensure_ascii=False,indent=2))
